/* Teknolojici15: Google Analytics 4 + AdSense loader (generated by build.mjs from engine/g.tpl.js).
   Consent Mode v2: EEA/UK/CH start "denied" until Google's certified CMP (AdSense Privacy & messaging)
   records a choice; elsewhere granted by default. No inline scripts, so the CSP stays 'self' for inline. */
(function () {
  var GA = '__GA4__', AD = '__ADS__';
  var w = window;
  w.dataLayer = w.dataLayer || [];
  function gtag() { w.dataLayer.push(arguments); }
  w.gtag = gtag;
  var EEA = ['AT','BE','BG','HR','CY','CZ','DK','EE','FI','FR','DE','GR','HU','IS','IE','IT','LV','LI','LT','LU','MT','NL','NO','PL','PT','RO','SK','SI','ES','SE','GB','CH'];
  gtag('consent', 'default', { ad_storage: 'denied', ad_user_data: 'denied', ad_personalization: 'denied', analytics_storage: 'denied', region: EEA, wait_for_update: 500 });
  gtag('consent', 'default', { ad_storage: 'granted', ad_user_data: 'granted', ad_personalization: 'granted', analytics_storage: 'granted' });
  gtag('set', 'ads_data_redaction', true);
  gtag('set', 'url_passthrough', true);

  var meta = function (n) { var m = document.querySelector('meta[name="t15:' + n + '"]'); return m ? m.content : ''; };
  if (GA) {
    gtag('js', new Date());
    gtag('config', GA, { content_group: meta('kind') || 'other', site_language: document.documentElement.lang || '', article_slug: meta('slug') || undefined });
  }
  var ev = function (name, p) { if (GA) gtag('event', name, p || {}); };

  function ready(fn) { if (document.readyState !== 'loading') fn(); else document.addEventListener('DOMContentLoaded', fn); }
  ready(function () {
    /* ad units: fill each <ins class="adsbygoogle"> once */
    if (AD) document.querySelectorAll('ins.adsbygoogle').forEach(function () { try { (w.adsbygoogle = w.adsbygoogle || []).push({}); } catch (e) {} });

    /* cookie settings link (Google CMP revocation message) */
    document.querySelectorAll('[data-cookie-settings]').forEach(function (b) {
      b.hidden = false;
      b.addEventListener('click', function (e) {
        e.preventDefault();
        w.googlefc = w.googlefc || {}; w.googlefc.callbackQueue = w.googlefc.callbackQueue || [];
        w.googlefc.callbackQueue.push(function () { if (w.googlefc.showRevocationMessage) w.googlefc.showRevocationMessage(); });
      });
    });
    if (!GA) return;

    /* clicks: sources, share, language, deck, internal recommendations, Instagram */
    document.addEventListener('click', function (e) {
      var a = e.target.closest('a,button'); if (!a) return;
      var href = a.getAttribute('href') || '';
      if (a.closest('.sources')) ev('source_click', { link_url: a.href, link_text: (a.textContent || '').slice(0, 100) });
      else if (a.closest('.share')) ev('share', { method: a.classList.contains('share__copy') ? 'copy_link' : (a.textContent || '').trim(), content_type: meta('kind'), item_id: meta('slug') });
      else if (a.closest('.lang__list')) ev('language_switch', { to_language: a.getAttribute('data-l') || '' });
      else if (a.closest('.deck')) ev('deck_nav', { direction: a.getAttribute('data-deck') || '' });
      else if (a.closest('.pager')) ev('pager_click', { direction: a.getAttribute('rel') || '' });
      else if (a.closest('.more,.nday,.tt__list,.toc,.tape')) ev('select_content', { content_type: 'recommendation', item_id: href });
      else if (/instagram\.com/.test(href)) ev('instagram_click', { link_url: href, placement: a.closest('header') ? 'header' : a.closest('footer') ? 'footer' : 'body' });
    }, true);

    /* reading depth for articles: 25/50/75/100 % of the article body, plus "reached sources" */
    var prose = document.querySelector('.prose');
    if (prose && 'IntersectionObserver' in w) {
      var marks = [25, 50, 75, 100], sent = {};
      var onScroll = function () {
        var r = prose.getBoundingClientRect(), h = prose.offsetHeight || 1;
        var pct = Math.max(0, Math.min(100, (w.innerHeight - r.top) / h * 100));
        marks.forEach(function (m) { if (pct >= m && !sent[m]) { sent[m] = 1; ev('read_progress', { percent: m, content_type: meta('kind'), item_id: meta('slug') }); } });
        if (sent[100]) w.removeEventListener('scroll', onScroll);
      };
      w.addEventListener('scroll', onScroll, { passive: true });
      var src = document.querySelector('.sources');
      if (src) { var io = new IntersectionObserver(function (es) { if (es[0].isIntersecting) { ev('read_complete', { content_type: meta('kind'), item_id: meta('slug') }); io.disconnect(); } }); io.observe(src); }
    }

    /* which ad slots were actually seen (helps compare placements) */
    if (AD && 'IntersectionObserver' in w) {
      var seen = new IntersectionObserver(function (es) { es.forEach(function (x) { if (x.isIntersecting) { ev('ad_slot_view', { slot_name: x.target.getAttribute('data-slot-name') || '' }); seen.unobserve(x.target); } }); }, { threshold: 0.5 });
      document.querySelectorAll('.ad').forEach(function (el) { seen.observe(el); });
    }
  });
})();
